#!/usr/bin/env node
// Deterministically generates apps-script-planning/AmplifyIm1ImportData.js
// from the canonical data/import-staging/amplify-im1.json artifact.
//
// Apps Script cannot read the local repository filesystem at runtime, so the
// artifact must be embedded as a checked-in JS constant. This script is the
// ONLY thing that writes that constant — never hand-edit the generated file.
//
// Byte-parity strategy: the embedded AMPLIFY_IM1_IMPORT_PAYLOAD is the exact
// same JSON text already on disk (not a re-derivation from the source
// transcription), so `JSON.stringify(AMPLIFY_IM1_IMPORT_PAYLOAD, null, 2) +
// "\n"` computed later inside Apps Script reproduces the original file's
// bytes exactly, and a SHA-256 of those bytes is recorded so the importer
// can detect drift or hand-editing at run time (see
// AmplifyIm1Importer.js's amplifyIm1ValidatePayloadIntegrity_).
//
// Usage: node scripts/import-staging/generate-apps-script-payload.mjs [--check]

import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, "..", "..");
const ARTIFACT_PATH = path.join(REPO_ROOT, "data/import-staging/amplify-im1.json");
const OUTPUT_PATH = path.join(REPO_ROOT, "apps-script-planning/AmplifyIm1ImportData.js");

function sha256Hex(input) {
  return createHash("sha256").update(input).digest("hex");
}

function countItems(units) {
  return units.reduce((total, unit) => total + unit.items.length, 0);
}

export function buildGeneratedFile() {
  if (!existsSync(ARTIFACT_PATH)) {
    throw new Error(
      `Canonical artifact not found at ${ARTIFACT_PATH}. Run generate-artifact.mjs first.`,
    );
  }
  const artifactText = readFileSync(ARTIFACT_PATH, "utf8");
  const artifact = JSON.parse(artifactText);
  const artifactSha256 = sha256Hex(artifactText);
  const unitCount = artifact.units.length;
  const itemCount = countItems(artifact.units);
  const confirmationPhrase = `IMPORT_AMPLIFY_IM1_${artifactSha256.slice(0, 12)}_${unitCount}_${itemCount}`;

  const metadata = {
    schemaVersion: artifact.schemaVersion,
    artifactPath: "data/import-staging/amplify-im1.json",
    artifactSha256,
    sourceDocument: artifact.generator.sourceDocument,
    sourceDocumentSha256: artifact.generator.sourceDocumentSha256,
    unitCount,
    itemCount,
    confirmationPhrase,
  };

  // artifactText already ends in exactly one trailing newline (see
  // generate-artifact.mjs's serialize()) — embedded verbatim so re-stringifying
  // AMPLIFY_IM1_IMPORT_PAYLOAD later reproduces these exact bytes.
  const payloadLiteral = artifactText.trimEnd();

  const lines = [
    "// ============================================================================",
    "// GENERATED FILE — DO NOT HAND-EDIT.",
    "//",
    "// Generated by scripts/import-staging/generate-apps-script-payload.mjs from",
    "// data/import-staging/amplify-im1.json (the canonical Amplify IM1 staging",
    "// artifact — see docs/Development/AMPLIFY_IM1_IMPORT_IMPLEMENTATION_SPEC.md,",
    "// Sprint 3/4, and scripts/import-staging/README.md).",
    "//",
    "// Re-run that generator to regenerate this file after the artifact changes:",
    "//   node scripts/import-staging/generate-apps-script-payload.mjs",
    "//   node scripts/import-staging/generate-apps-script-payload.mjs --check",
    "//",
    "// Contains only publisher-owned curriculum data. No PlannedDays,",
    "// TeacherNotes, PrimaryLink, progress, or Lesson Session data appears here —",
    "// see the field-ownership map in AmplifyIm1Importer.js.",
    "// ============================================================================",
    "",
    `const AMPLIFY_IM1_IMPORT_PAYLOAD = Object.freeze(${payloadLiteral});`,
    "",
    `const AMPLIFY_IM1_IMPORT_METADATA = Object.freeze(${JSON.stringify(metadata, null, 2)});`,
    "",
    "// Allows this file's constants to be loaded from Node for local testing",
    "// (see scripts/import-staging/importer.test.mjs) without affecting Apps",
    '// Script, where the global `module` identifier does not exist — `typeof`',
    "// guards against that safely.",
    "if (typeof module !== \"undefined\" && module.exports) {",
    "  module.exports = { AMPLIFY_IM1_IMPORT_PAYLOAD, AMPLIFY_IM1_IMPORT_METADATA };",
    "}",
    "",
  ];

  return lines.join("\n");
}

function main() {
  const checkOnly = process.argv.includes("--check");
  const generated = buildGeneratedFile();

  if (checkOnly) {
    if (!existsSync(OUTPUT_PATH)) {
      console.error(`FAIL: ${OUTPUT_PATH} does not exist yet.`);
      process.exit(1);
    }
    const onDisk = readFileSync(OUTPUT_PATH, "utf8");
    if (onDisk !== generated) {
      console.error(
        "FAIL: regenerating the Apps Script payload produced different bytes than what's on disk. " +
          "Run without --check to regenerate.",
      );
      process.exit(1);
    }
    console.log("OK: AmplifyIm1ImportData.js matches a fresh deterministic regeneration (no diff).");
    return;
  }

  writeFileSync(OUTPUT_PATH, generated, "utf8");
  console.log(`Wrote ${OUTPUT_PATH} (${generated.length} bytes).`);
}

if (fileURLToPath(import.meta.url) === path.resolve(process.argv[1] ?? "")) {
  main();
}
